function load(){try{const raw=localStorage.getItem(STORE);if(raw){const d=JSON.parse(raw);if(Array.isArray(d.products)&&Array.isArray(d.orders)&&Array.isArray(d.ingredients)&&d.settings){for(const p of BASE_PRODUCTS.filter(p=>['coffee','tea'].includes(p.id)))if(!d.products.some(x=>x.id===p.id))d.products.push({...p});return d}}}catch(e){console.warn(e)}return DEFAULT()}
