const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const euro=n=>Number(n||0).toLocaleString('de-DE',{style:'currency',currency:'EUR'});const dt=s=>new Date(s).toLocaleString('ru-RU',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'});const day=s=>new Date(s).toDateString();const today=()=>day(new Date());
const statuses={new:['Новый','new'],accepted:['Принят','accepted'],cooking:['Готовится','cooking'],ready:['Готов','ready'],done:['Выдан','done'],cancelled:['Отменён','cancelled'],pending:['Ожидает','pending']};const cats={shawarma:'Шаурма',combos:'Комбо',sides:'Закуски',drinks:'Напитки'};const titles={dashboard:'Главная',orders:'Заказы',menu:'Меню',ingredients:'Ингредиенты',stats:'Статистика заказов',analytics:'Аналитика сайта',truck:'Продажи фудтрака',settings:'Настройки',messages:'Сообщения'};
function badge(status){return `<span class="status ${esc(status)}">${statuses[status]?.[0]||esc(status)}</span>`}
function total(o){return o.items.reduce((s,i)=>s+(data.products.find(p=>p.id===i.id)?.price||BASE_PRODUCTS.find(p=>p.id===i.id)?.price||0)*i.qty,0)}
function isSale(o){return o.status==='done'}
function orderRows(orders,compact=false){return `<div class="table-wrap"><table class="table"><thead><tr><th>Заказ</th><th>Время</th><th>Состав</th><th>Сумма</th><th>Статус</th><th></th></tr></thead><tbody>${orders.map(o=>`<tr><td class="strong">${esc(o.id)}</td><td class="muted">${dt(o.date)}</td><td>${o.items.reduce((s,i)=>s+i.qty,0)} поз.</td><td class="strong">${euro(total(o))}</td><td>${badge(o.status)}</td><td><button class="btn small" data-view-order="${esc(o.id)}">Открыть</button></td></tr>`).join('')}</tbody></table>${!orders.length?'<div class="empty">Ничего не найдено</div>':''}</div>`}
function heading(title,sub,action=''){return `<div class="page-head"><div><div class="eyebrow">SCHAWA GRILL / ADMIN</div><h1>${title}</h1><p class="sub">${sub}</p></div>${action}</div>`}
function render(){if(page==='messages')page='dashboard'; $('#crumbTitle').textContent=titles[page];$$('.nav-link').forEach(b=>b.classList.toggle('active',b.dataset.page===page));const f={dashboard,orders,menu,ingredients,stats,analytics,truck,settings,messages}[page];$('#content').innerHTML=f(); updateMessageCount(); }
let businessPeriod='7', businessMetric='orders', businessSource='all', businessFrom='',businessTo='';
const channelNames={site:'Сайт',instagram:'Instagram',whatsapp:'WhatsApp',truck:'На месте',other:'Не указан'};
function channel(o){const v=String(o.source||'').toLowerCase();return /сайт|site|web/.test(v)?'site':/instagram|инст/.test(v)?'instagram':/whatsapp|ватс/.test(v)?'whatsapp':/truck|касс|на месте/.test(v)?'truck':'other'}
function businessOrders(){try{return JSON.parse(localStorage.getItem('schawa-kitchen-demo-v1'))?.orders||[]}catch{return []}}
function dateKey(v){const d=new Date(v);if(!Number.isFinite(+d))return '';return new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Berlin',year:'numeric',month:'2-digit',day:'2-digit'}).format(d)}
function inBusinessPeriod(k){const end=dateKey(new Date());const d=new Date(end+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-Number(businessPeriod==='custom'?1:businessPeriod)+1);return k>=(businessPeriod==='custom'?businessFrom:d.toISOString().slice(0,10))&&k<=(businessPeriod==='custom'?businessTo:end)}
function orderValue(o){return o.items.reduce((a,i)=>a+Number(i.price??data.products.find(p=>p.id===i.id)?.price??0)*Number(i.qty||0),0)}
function dashboard(){const all=businessOrders().filter(o=>inBusinessPeriod(dateKey(o.date))), os=all.filter(o=>businessSource==='all'||channel(o)===businessSource), rows=truckData.rows.filter(r=>inBusinessPeriod(r.date)), done=os.filter(o=>o.status==='done'), active=os.filter(o=>!['done','cancelled','no_show'].includes(o.status)), bad=os.filter(o=>['cancelled','no_show'].includes(o.status)), ratings=done.filter(o=>Number(o.rating)>=1&&Number(o.rating)<=5), sum=rows.reduce((a,r)=>a+r.amount,0), metric=(n,v,sub)=>`<div class="card metric"><div class="metric-top">${n}</div><div class="metric-value">${v}</div><div class="metric-bottom">${sub}</div></div>`;
const heat=Array.from({length:7},()=>Array(24).fill(0));for(const o of os){const k=dateKey(o.date),h=Number(new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Berlin',hour:'2-digit',hourCycle:'h23'}).format(new Date(o.date))),w=(new Date(k+'T12:00:00Z').getUTCDay()+6)%7;if(businessMetric==='orders')heat[w][h]++;else if(o.status==='done')heat[w][h]+=o.items.filter(i=>/classic|xl|spicy|cheese|mushroom|hawaii/.test(i.id)).reduce((a,i)=>a+Number(i.qty),0)}const max=Math.max(1,...heat.flat());
return heading('Обзор бизнеса','Заказы терминала и продажи фудтрака · время Мюнхена')+`<div class="notice">Локальные данные терминала. Продажи фудтрака — отдельный демонстрационный CSV-отчёт; не складываем суммы без сверки чеков.</div><div class="business-filters"><select id="businessPeriod" class="select">${[['1','Сегодня'],['7','7 дней'],['30','30 дней'],['custom','Период']].map(([v,n])=>`<option value="${v}" ${businessPeriod===v?'selected':''}>${n}</option>`).join('')}</select>${businessPeriod==='custom'?`<input type="date" id="businessFrom" value="${esc(businessFrom)}"><input type="date" id="businessTo" value="${esc(businessTo)}">`:''}<select id="businessSource" class="select"><option value="all">Все источники</option>${Object.entries(channelNames).map(([k,n])=>`<option value="${k}" ${businessSource===k?'selected':''}>${n}</option>`).join('')}</select></div><div class="metrics home-metrics">${metric('Заказы терминала',os.length,'Все статусы')}${metric('Выдано',done.length,os.length?Math.round(done.length/os.length*100)+'% заказов':'Нет заказов')}${metric('В работе',active.length,'Активная очередь')}${metric('Не забрали',os.filter(o=>o.status==='no_show').length,'Не означает мошенничество')}${metric('Отменено',os.filter(o=>o.status==='cancelled').length,'Все отмены')}${metric('Оценка',ratings.length?(ratings.reduce((a,o)=>a+Number(o.rating),0)/ratings.length).toFixed(1)+' / 5':'—',ratings.length+' оценок')}${metric('Сумма выданных',euro(done.reduce((a,o)=>a+orderValue(o),0)),'Не подтверждённая оплата')}${metric('Фудтрак · CSV',euro(sum),rows.length+' строк продаж, не заказов')}</div><section class="card business-section"><h2>Источники заказов</h2><div class="table-wrap"><table class="table"><thead><tr><th>Канал</th><th>Всего</th><th>Выдано</th><th>В работе</th><th>Отменено</th><th>Не забрали</th></tr></thead><tbody>${Object.entries(channelNames).map(([k,n])=>{const a=os.filter(o=>channel(o)===k);return `<tr><td><strong>${n}</strong></td><td>${a.length}</td><td>${a.filter(o=>o.status==='done').length}</td><td>${a.filter(o=>!['done','cancelled','no_show'].includes(o.status)).length}</td><td>${a.filter(o=>o.status==='cancelled').length}</td><td>${a.filter(o=>o.status==='no_show').length}</td></tr>`}).join('')}</tbody></table></div></section><section class="card business-section"><div class="card-title"><h2>Тепловая карта · терминал</h2><select id="businessMetric" class="select"><option value="orders" ${businessMetric==='orders'?'selected':''}>Заказы</option><option value="shawarma" ${businessMetric==='shawarma'?'selected':''}>Выданная шаурма</option></select></div><div class="business-heat-scroll"><div class="business-heat"><span></span>${Array.from({length:24},(_,h)=>`<small>${h}:00</small>`).join('')}${heat.map((r,w)=>`<b>${TRUCK_DAYS[w]}</b>${r.map((n,h)=>`<button class="heat-cell" data-heat="${w},${h},${n}" style="background:${n?'rgba(18,117,72,'+(.16+.84*n/max)+')':'#edf2ef'};color:${n/max>.55?'white':'#164c35'}" title="${TRUCK_DAYS[w]} ${h}:00 — ${n}">${n||'·'}</button>`).join('')}`).join('')}</div></div><p id="heatDetail" class="sub">Нажмите на ячейку для подробностей. Светлый — мало, тёмный — много.</p></section><section class="card business-section"><h2>Проблемные заказы</h2><p class="sub">Фальшивые заказы не определяются автоматически.</p><div class="table-wrap"><table class="table"><thead><tr><th>Номер</th><th>Источник</th><th>Время</th><th>Статус</th><th>Сумма заказа</th></tr></thead><tbody>${bad.map(o=>`<tr><td>${esc(o.id)}</td><td>${channelNames[channel(o)]}</td><td>${dt(o.date)}</td><td>${o.status==='no_show'?'Не забрали':'Отменён'}</td><td>${euro(orderValue(o))}</td></tr>`).join('')}</tbody></table></div>${bad.length?'':'<p class="empty">Нет проблемных заказов</p>'}</section><section class="card business-section"><h2>Финансы и расходы</h2><p>Отдельный этап: Telegram-бот, распознавание чеков, подтверждение категорий и сверка с кассой. Прибыль пока не рассчитывается.</p></section>`}
document.addEventListener('change',e=>{const t=e.target;if(t.id==='businessPeriod'){businessPeriod=t.value;if(!businessFrom)businessFrom=dateKey(new Date());if(!businessTo)businessTo=dateKey(new Date())}else if(t.id==='businessSource')businessSource=t.value;else if(t.id==='businessMetric')businessMetric=t.value;else if(t.id==='businessFrom')businessFrom=t.value;else if(t.id==='businessTo')businessTo=t.value;else return;render()});
document.addEventListener('click',e=>{const b=e.target.closest('[data-heat]');if(!b)return;const [w,h,n]=b.dataset.heat.split(',').map(Number);$('#heatDetail').textContent=TRUCK_DAYS[w]+' · '+h+':00–'+(h+1)+':00 · '+n+(businessMetric==='orders'?' заказов':' порций')});
function chart(n){const values=Array.from({length:n},(_,i)=>{const d=new Date(now);d.setDate(d.getDate()-(n-1-i));return {label:d.toLocaleDateString('ru-RU',{day:'2-digit',month:'2-digit'}),value:data.orders.filter(o=>isSale(o)&&day(o.date)===day(d)).reduce((s,o)=>s+total(o),0)}});const max=Math.max(...values.map(v=>v.value),1);return `<div class="chart" role="img" aria-label="Выручка по дням">${values.map((v,i)=>`<div class="chart-col"><div class="chart-value">${v.value?Math.round(v.value)+'€':''}</div><div class="chart-bar ${i===n-1?'highlight':''}" style="height:${Math.max(v.value/max*145,3)}px" title="${v.label}: ${euro(v.value)}"></div><div class="chart-label">${v.label}</div></div>`).join('')}</div>`}
function ranking(orders){const m=new Map();orders.forEach(o=>o.items.forEach(i=>m.set(i.id,(m.get(i.id)||0)+i.qty)));return [...m].sort((a,b)=>b[1]-a[1]).map(([id,qty])=>({name:data.products.find(p=>p.id===id)?.name||BASE_PRODUCTS.find(p=>p.id===id)?.name||id,qty}))}
function rankRow(x,i,max){return `<div class="rank"><div class="rank-num">${String(i+1).padStart(2,'0')}</div><div class="rank-info"><strong>${esc(x.name)}</strong><div class="rank-track"><div class="rank-fill" style="width:${Math.round(x.qty/max*100)}%"></div></div></div><div class="rank-count">${x.qty}</div></div>`}
function orders(){let list=[...data.orders].sort((a,b)=>new Date(b.date)-new Date(a.date));if(orderFilter!=='all')list=list.filter(o=>o.status===orderFilter);if(orderSearch)list=list.filter(o=>o.id.toLowerCase().includes(orderSearch.toLowerCase()));return heading('Заказы','История, детали и статусы тестовых заказов',`<button class="btn primary" data-add-order="1">＋ Новый демо-заказ</button>`)+`<div class="card"><div class="toolbar"><input class="input search" id="orderSearch" placeholder="Поиск по номеру заказа" value="${esc(orderSearch)}"><select class="select" id="orderFilter" style="width:auto"><option value="all">Все статусы</option>${Object.entries(statuses).map(([k,v])=>`<option value="${k}" ${orderFilter===k?'selected':''}>${v[0]}</option>`).join('')}</select><span class="mini-stat">${list.length} заказов</span></div>${orderRows(list)}</div>`}
function menu(){let list=data.products.filter(p=>(menuCategory==='all'||p.category===menuCategory)&&p.name.toLowerCase().includes(menuSearch.toLowerCase()));return heading('Меню','Управление товарами, ценами и доступностью',`<button class="btn primary" data-add-product="1">＋ Добавить товар</button>`)+`<div class="toolbar"><input class="input search" id="menuSearch" placeholder="Поиск по названию" value="${esc(menuSearch)}">${[['all','Все'],...Object.entries(cats)].map(([k,v])=>`<button class="filter-chip ${menuCategory===k?'active':''}" data-category="${k}">${v}</button>`).join('')}</div><div class="grid-products">${list.map(p=>`<article class="card product-card"><img src="../assets/${esc(p.image)}" alt=""><div class="product-body"><div class="eyebrow">${cats[p.category]||'Товар'}</div><h3>${esc(p.name)}</h3><p>${esc(p.desc)}</p><div class="product-foot"><strong>${euro(p.price)}</strong><div class="product-actions"><input class="toggle" type="checkbox" data-toggle-product="${esc(p.id)}" ${p.active?'checked':''} title="Доступен" aria-label="Доступность ${esc(p.name)}"><button class="btn small" data-edit-product="${esc(p.id)}">Изменить</button></div></div></div></article>`).join('')}</div>${!list.length?'<div class="card empty">Товары не найдены</div>':''}`}
function ingredients(){return heading('Ингредиенты','Дополнения, цены и доступность')+`<div class="notice">В демо изменение ингредиентов не меняет состав и стоимость товаров на публичном сайте. После подключения backend эта логика будет общей.</div><section class="card"><div class="card-title"><h2>Состав и добавки</h2><span class="mini-stat">${data.ingredients.length} позиций</span></div><div class="ingredient-list">${data.ingredients.map(i=>`<div class="ingredient-row"><img src="../assets/${esc(i.image)}" alt=""><div class="name">${esc(i.name)}<small>Доплата: ${i.price?euro(i.price):'Бесплатно'}</small></div><input type="checkbox" class="toggle" data-toggle-ingredient="${esc(i.id)}" ${i.active?'checked':''} aria-label="Доступность ${esc(i.name)}"><button class="icon-btn" data-edit-ingredient="${esc(i.id)}" title="Редактировать">✎</button></div>`).join('')}</div></section>`}
